import 'dart:async';import 'dart:io';import 'package:flutter/foundation.dart';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:flutter_animate/flutter_animate.dart';import 'package:path_provider/path_provider.dart';import 'package:shared_preferences/shared_preferences.dart';import 'package:audioplayers/audioplayers.dart' as ap;import 'package:http/http.dart' as http;import 'package:record/record.dart';import '../theme/app_colors.dart';import '../theme/app_typography.dart';import '../widgets/brand_background.dart';import '../widgets/brand_card.dart';import '../widgets/brand_button.dart';import '../services/haptic_service.dart';import '../services/pronunciation_service.dart';import '../services/supabase_storage_service.dart';import '../services/supabase_dataset_service.dart';import '../models/supabase_dataset_entry.dart';import '../models/quest.dart';import '../providers/student_provider.dart';import '../providers/quest_provider.dart';import '../utils/wav_decoder.dart';import '../utils/audio_bytes_decoder.dart';import '../utils/app_localization.dart';import '../services/firebase_service.dart';enum AudioComparisonState {  idle,       // Ready to start recording  recording,  // Microhpone is actively capturing audio  recorded,   // Recording complete, preview & review available  playing,    // Playing back learner's recorded attempt  comparing,  // Executing candidate pronunciation comparison  result,     // Comparison complete, candidate score presented  error,      // Recoverable error message}class AudioComparisonScreen extends ConsumerStatefulWidget {  const AudioComparisonScreen({super.key});  @override  ConsumerState<AudioComparisonScreen> createState() => _AudioComparisonScreenState();}class _AudioComparisonScreenState extends ConsumerState<AudioComparisonScreen> {  static const int maxRecordingDurationSeconds = 15;  AudioComparisonState _state = AudioComparisonState.idle;  double _scorePercentage = 0.0;  bool _isMismatchResult = false;  String _resultFeedback = "";  int _currentIndex = 0;  bool _isShuffled = false;  /// Learner-facing practice items: primary dataset references only (take 1 default).  /// dataset_2 entries are excluded here and used only for comparison accuracy.  List<SupabaseDatasetEntry> _items = [];  /// Full pool (primary + supplementary dataset_2 takes) for multi-reference comparison.  List<SupabaseDatasetEntry> _comparisonEntries = [];  bool _isLoadingNativeAudio = false;  String? _recordedFilePath;  Uint8List? _preprocessedWavBytes;  double _recordedDurationSeconds = 0.0;  int _recordingDurationSeconds = 0;  Timer? _recordingTimer;  StreamSubscription<Amplitude>? _amplitudeSubscription;  final List<double> _liveAmplitudeBars = List.filled(16, 0.1);  List<double> _userVisualWaveform = [];  List<double> _nativeVisualWaveform = [];  String? _errorMessage;  bool _isQuietWarning = false;  bool _isStoppingRecording = false;  final AudioRecorder _audioRecorder = AudioRecorder();  final ap.AudioPlayer _nativePlayer = ap.AudioPlayer();  final ap.AudioPlayer _userPlayer = ap.AudioPlayer();  StreamSubscription? _userPlayerCompleteSubscription;  @override  void initState() {    super.initState();    _userPlayerCompleteSubscription = _userPlayer.onPlayerComplete.listen((_) {      if (mounted && _state == AudioComparisonState.playing) {        setState(() {          _state = AudioComparisonState.recorded;        });      }    });    WidgetsBinding.instance.addPostFrameCallback((_) {      _checkUnlockMilestoneOnOpen();    });  }  Future<void> _checkUnlockMilestoneOnOpen() async {    try {      final prefs = await SharedPreferences.getInstance();      final studentState = ref.read(studentProvider);      final currentTier = studentState.xp ~/ 2000;      final lastSeenTier = prefs.getInt('audio_comparison_last_seen_tier') ?? 0;      if (currentTier > lastSeenTier) {        await prefs.setInt('audio_comparison_last_seen_tier', currentTier);        final unlockedNewCount = (currentTier - lastSeenTier) * 10;        if (mounted) {          _showUnlockCongratulationsDialog(unlockedNewCount, studentState.xp);        }      }    } catch (e) {      debugPrint('Error checking unlock milestone on open: $e');    }  }  void _showUnlockCongratulationsDialog(int unlockedNewCount, int currentXp) {    final isDark = Theme.of(context).brightness == Brightness.dark;    showDialog(      context: context,      builder: (context) => AlertDialog(        backgroundColor: isDark ? AppColors.forest700 : AppColors.creamBg,        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),        title: Row(          children: [            const Icon(Icons.celebration_rounded, color: AppColors.gold500, size: 28),            const SizedBox(width: 12),            Expanded(              child: Text(                "Congrats! You've Unlocked New Audio!",                style: AppTypography.h3.copyWith(color: isDark ? Colors.white : AppColors.creamText, fontSize: 18),              ),            ),          ],        ),        content: Text(          "You reached $currentXp XP and unlocked $unlockedNewCount new audio recordings! Keep practicing to master all tribal phrases.",          style: AppTypography.body.copyWith(color: isDark ? Colors.white70 : AppColors.creamText2),        ),        actions: [          BrandButton(            text: "AWESOME!",            onTap: () {              Navigator.pop(context);              HapticService.success();            },            type: BrandButtonType.primary,          ),        ],      ),    );  }  Widget _buildUnlockStatusBanner(bool isDark, int currentXp, int unlockedCount, int totalCount) {    final nextMilestone = ((currentXp ~/ 2000) + 1) * 2000;    final xpNeeded = nextMilestone - currentXp;    return Container(      margin: const EdgeInsets.only(bottom: 16),      padding: const EdgeInsets.all(12),      decoration: BoxDecoration(        color: AppColors.gold500.withValues(alpha: 0.15),        borderRadius: BorderRadius.circular(16),        border: Border.all(color: AppColors.gold500.withValues(alpha: 0.4)),      ),      child: Row(        children: [          const Icon(Icons.lock_open_rounded, color: AppColors.gold500, size: 24),          const SizedBox(width: 12),          Expanded(            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Text(                  'Unlocked: $unlockedCount / $totalCount Recordings',                  style: AppTypography.label.copyWith(color: AppColors.gold500, fontWeight: FontWeight.bold, fontSize: 13),                ),                const SizedBox(height: 2),                Text(                  xpNeeded > 0                      ? 'Reach $nextMilestone XP to unlock 10 more audio recordings (easiest to hardest)!'                      : 'All audio recordings unlocked!',                  style: AppTypography.caption.copyWith(color: isDark ? Colors.white70 : AppColors.creamText2, fontSize: 11),                ),              ],            ),          ),        ],      ),    );  }  @override  void dispose() {    _recordingTimer?.cancel();    _amplitudeSubscription?.cancel();    _userPlayerCompleteSubscription?.cancel();    _audioRecorder.dispose();    _nativePlayer.dispose();    _userPlayer.dispose();    super.dispose();  }  Future<void> _playNativeAudio(SupabaseDatasetEntry item) async {    if (item.takes.isEmpty) return;    final take = item.primaryTake ?? item.takes.first;    if (take.audioUrl.isEmpty) return;    setState(() => _isLoadingNativeAudio = true);    try {      await _userPlayer.stop();      final resolvedUrl = ref.read(supabaseStorageServiceProvider).getAudioUrl(take.audioUrl);      await _nativePlayer.stop();      await _nativePlayer.play(ap.UrlSource(resolvedUrl));    } catch (e) {      debugPrint('Error playing native reference audio: $e');      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          SnackBar(            content: Text('Failed to play reference audio: ${e.toString().split(':').last.trim()}'),            backgroundColor: AppColors.semanticRed,          ),        );      }    } finally {      if (mounted) setState(() => _isLoadingNativeAudio = false);    }  }  Future<List<double>> _fetchAndDecodeNativePcm(SupabaseDatasetEntry currentItem, ReferenceAudioTake take) async {    Uint8List nativeBytes;    File? nativeFile;    final resolvedNativeUrl = ref.read(supabaseStorageServiceProvider).getAudioUrl(take.audioUrl);    if (kIsWeb) {      final response = await http.get(Uri.parse(resolvedNativeUrl)).timeout(const Duration(seconds: 15));      if (response.statusCode == 200 && response.bodyBytes.isNotEmpty) {        nativeBytes = response.bodyBytes;      } else {        throw Exception('Failed to download reference WAV (HTTP ${response.statusCode})');      }    } else {      final directory = await getTemporaryDirectory();      final cacheFileName = buildReferenceCacheFileName(currentItem.folderName, take.runId, take.takeNumber);      nativeFile = File('${directory.path}/$cacheFileName');      bool needsDownload = true;      if (await nativeFile.exists()) {        if (await nativeFile.length() > 500) {          needsDownload = false;        } else {          await nativeFile.delete();        }      }      if (needsDownload) {        final response = await http.get(Uri.parse(resolvedNativeUrl)).timeout(const Duration(seconds: 15));        if (response.statusCode == 200) {          await nativeFile.writeAsBytes(response.bodyBytes);        } else {          throw Exception('Failed to download reference WAV (HTTP ${response.statusCode})');        }      }      nativeBytes = await nativeFile.readAsBytes();    }    return (await decodeAudioBytes(nativeBytes)).pcmSamples;  }  static const int _maxReferenceTakes = 6;  /// Every verified take of this phrase across all compatible runs, ordered so  /// that each run contributes a take before any run contributes a second one.  /// Comparing against one take made the score depend on how typical that single  /// recording happened to be.  List<ReferenceAudioTake> _collectReferenceTakes(SupabaseDatasetEntry currentItem) {    final byRun = <String, List<ReferenceAudioTake>>{};    final seenPaths = <String>{};    final pool = _comparisonEntries.isNotEmpty ? _comparisonEntries : _items;    for (final entry in pool) {      if (entry.folderName != currentItem.folderName) continue;      if (!entry.isCompatible || !entry.isAvailable) continue;      final takes = byRun.putIfAbsent(entry.runId, () => <ReferenceAudioTake>[]);      for (final take in entry.takes) {        if (seenPaths.add(take.audioPath)) takes.add(take);      }    }    final runs = byRun.keys.toList()..sort();    for (final run in runs) {      byRun[run]!.sort((a, b) => a.takeNumber.compareTo(b.takeNumber));    }    final ordered = <ReferenceAudioTake>[];    var takeIndex = 0;    while (ordered.length < _maxReferenceTakes) {      var addedAny = false;      for (final run in runs) {        final takes = byRun[run]!;        if (takeIndex >= takes.length) continue;        ordered.add(takes[takeIndex]);        addedAny = true;        if (ordered.length >= _maxReferenceTakes) break;      }      if (!addedAny) break;      takeIndex++;    }    return ordered;  }  PronunciationAlgorithm _configuredAlgorithm() {    final config = ref.read(appConfigProvider).value;    final configuredName = config?.activePronunciationAlgorithm ?? 'dtw';    return PronunciationAlgorithm.values.firstWhere(      (algorithm) => algorithm.name == configuredName,      orElse: () => PronunciationAlgorithm.dtw,    );  }  Future<void> _playUserAudio() async {    if (_recordedFilePath == null || _recordedFilePath!.isEmpty) return;    try {      await _nativePlayer.stop();      await _userPlayer.stop();      await _ensurePreprocessedWavBytes();      if (_preprocessedWavBytes != null) {        await _userPlayer.play(ap.BytesSource(_preprocessedWavBytes!));      } else if (!kIsWeb && File(_recordedFilePath!).existsSync()) {        await _userPlayer.play(ap.DeviceFileSource(_recordedFilePath!));      } else if (kIsWeb) {        await _userPlayer.play(ap.UrlSource(_recordedFilePath!));      } else {        return;      }      setState(() {        _state = AudioComparisonState.playing;      });    } catch (e) {      debugPrint('Error playing learner attempt audio: $e');    }  }  Future<void> _ensurePreprocessedWavBytes() async {    if (_preprocessedWavBytes != null) return;    if (_recordedFilePath == null || _recordedFilePath!.isEmpty) return;    try {      Uint8List? bytes;      if (kIsWeb) {        final response = await http.get(Uri.parse(_recordedFilePath!));        if (response.statusCode == 200) bytes = response.bodyBytes;      } else {        final file = File(_recordedFilePath!);        if (await file.exists()) bytes = await file.readAsBytes();      }      if (bytes == null || bytes.isEmpty) return;      final decoded = await decodeAudioBytes(bytes);      if (decoded.pcmSamples.isEmpty) return;      final preprocessedPcm = WavDecoder.prepareLearnerPcm(decoded.pcmSamples);      _preprocessedWavBytes =          WavDecoder.encodePcmToWavBytes(preprocessedPcm, sampleRate: 16000);    } catch (e) {      debugPrint('Failed to generate preprocessed preview: $e');    }  }  Future<void> _stopUserAudio() async {    try {      await _userPlayer.stop();      if (mounted && _state == AudioComparisonState.playing) {        setState(() {          _state = AudioComparisonState.recorded;        });      }    } catch (e) {      debugPrint('Error stopping learner audio playback: $e');    }  }  void _nextItem() {    if (_currentIndex < _items.length - 1) {      _stopAllAudioAndRecording();      setState(() {        _currentIndex++;        _state = AudioComparisonState.idle;        _scorePercentage = 0.0;        _isMismatchResult = false;        _resultFeedback = "";        _recordedFilePath = null;        _userVisualWaveform = [];        _nativeVisualWaveform = [];        _errorMessage = null;        _isQuietWarning = false;      });      HapticService.light();    }  }  void _previousItem() {    if (_currentIndex > 0) {      _stopAllAudioAndRecording();      setState(() {        _currentIndex--;        _state = AudioComparisonState.idle;        _scorePercentage = 0.0;        _isMismatchResult = false;        _resultFeedback = "";        _recordedFilePath = null;        _userVisualWaveform = [];        _nativeVisualWaveform = [];        _errorMessage = null;        _isQuietWarning = false;      });      HapticService.light();    }  }  void _toggleShuffle() {    if (_items.isEmpty) return;    _stopAllAudioAndRecording();    setState(() {      _isShuffled = !_isShuffled;      _items.shuffle();      _currentIndex = 0;      _state = AudioComparisonState.idle;      _scorePercentage = 0.0;      _recordedFilePath = null;      _userVisualWaveform = [];      _nativeVisualWaveform = [];      _errorMessage = null;      _isQuietWarning = false;    });    HapticService.medium();  }  Future<void> _stopAllAudioAndRecording() async {    _recordingTimer?.cancel();    _amplitudeSubscription?.cancel();    try {      if (await _audioRecorder.isRecording()) {        await _audioRecorder.stop();      }    } catch (_) {}    try {      await _nativePlayer.stop();      await _userPlayer.stop();    } catch (_) {}  }  Future<void> _startRecording() async {    if (_state == AudioComparisonState.recording || _state == AudioComparisonState.comparing) return;    HapticService.selection();    await _stopAllAudioAndRecording();    // Check microphone permission    bool hasPermission = false;    try {      hasPermission = await _audioRecorder.hasPermission();    } catch (e) {      debugPrint('Permission check error: $e');    }    if (!hasPermission) {      if (mounted) {        setState(() {          _state = AudioComparisonState.error;          _errorMessage = 'Microphone permission is required to record audio.';        });        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text('Microphone permission is required to record audio.'),            backgroundColor: AppColors.semanticRed,          ),        );      }      return;    }    try {      RecordConfig config = const RecordConfig(        encoder: AudioEncoder.wav,        sampleRate: 16000,        numChannels: 1,        autoGain: false,        echoCancel: false,      );      bool isWavSupported = true;      try {        isWavSupported = await _audioRecorder.isEncoderSupported(AudioEncoder.wav);      } catch (_) {}      if (!isWavSupported) {        config = const RecordConfig(          encoder: AudioEncoder.pcm16bits,          sampleRate: 16000,          numChannels: 1,          autoGain: true,          echoCancel: true,        );      }      String recordPath = '';      if (!kIsWeb) {        final directory = await getTemporaryDirectory();        recordPath = '${directory.path}/user_pronunciation_16k.wav';      }      await _audioRecorder.start(config, path: recordPath);      _recordingDurationSeconds = 0;      _isStoppingRecording = false;      _recordingTimer?.cancel();      _recordingTimer = Timer.periodic(const Duration(seconds: 1), (timer) {        if (mounted && _state == AudioComparisonState.recording) {          setState(() {            _recordingDurationSeconds++;          });          if (_recordingDurationSeconds >= maxRecordingDurationSeconds) {            _stopRecording(isAutoStop: true);          }        }      });      _amplitudeSubscription?.cancel();      _amplitudeSubscription = _audioRecorder.onAmplitudeChanged(const Duration(milliseconds: 100)).listen((amp) {        if (mounted && _state == AudioComparisonState.recording) {          setState(() {            final norm = ((amp.current + 60) / 60).clamp(0.08, 1.0);            _liveAmplitudeBars.removeAt(0);            _liveAmplitudeBars.add(norm);          });        }      });      if (mounted) {        setState(() {          _recordedFilePath = kIsWeb ? null : recordPath;          _state = AudioComparisonState.recording;          _errorMessage = null;          _isQuietWarning = false;        });      }    } catch (e) {      debugPrint('Failed to start recording: $e');      _recordingTimer?.cancel();      _amplitudeSubscription?.cancel();      if (mounted) {        setState(() {          _state = AudioComparisonState.error;          _errorMessage = 'Could not start microphone capture: ${e.toString().split(':').last.trim()}';          _isQuietWarning = false;        });        ScaffoldMessenger.of(context).showSnackBar(          SnackBar(            content: Text(_errorMessage!),            backgroundColor: AppColors.semanticRed,          ),        );      }    }  }  Future<void> _stopRecording({bool isAutoStop = false}) async {    if (_state != AudioComparisonState.recording || _isStoppingRecording) return;    _isStoppingRecording = true;    HapticService.selection();    _recordingTimer?.cancel();    _amplitudeSubscription?.cancel();    try {      final path = await _audioRecorder.stop();      final targetPath = path ?? _recordedFilePath;      if (targetPath == null || targetPath.isEmpty) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = 'Recording output is missing.';            _isQuietWarning = false;          });        }        return;      }      Uint8List bytes;      if (kIsWeb) {        if (!targetPath.startsWith('blob:') && !targetPath.startsWith('http')) {          if (mounted) {            setState(() {              _state = AudioComparisonState.error;              _errorMessage = 'Recording failed to generate a valid browser audio URL.';              _isQuietWarning = false;            });          }          return;        }        final response = await http.get(Uri.parse(targetPath));        if (response.statusCode != 200 || response.bodyBytes.isEmpty) {          if (mounted) {            setState(() {              _state = AudioComparisonState.error;              _errorMessage = 'Failed to retrieve recorded audio in browser.';              _isQuietWarning = false;            });          }          return;        }        bytes = response.bodyBytes;      } else {        final learnerFile = File(targetPath);        if (!learnerFile.existsSync() || await learnerFile.length() < 100) {          if (mounted) {            setState(() {              _state = AudioComparisonState.error;              _errorMessage = 'Recording is empty. Please speak clearly and try again.';              _isQuietWarning = false;            });          }          return;        }        bytes = await learnerFile.readAsBytes();      }      if (bytes.length < 100) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = 'Recording is empty. Please speak clearly and try again.';            _isQuietWarning = false;          });        }        return;      }      final learnerWavResult = await decodeAudioBytes(bytes);      final learnerPcm = learnerWavResult.pcmSamples;      if (learnerPcm.length < WavDecoder.minimumComparisonSamples) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = 'Recording is too short to compare reliably (minimum 0.35 seconds). Please say the full word and record again.';            _isQuietWarning = false;          });        }        return;      }      // Check signal for silence/near-silence and quality conditions      final signal = WavDecoder.analyzeSignal(learnerPcm);      if (signal.isEmptyOrInvalid || signal.isSilent || signal.isQuiet || signal.hasNoSpeech) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = signal.hasNoSpeech                ? "No speech detected. Please speak the phrase clearly into the microphone and record again."                : "We couldn't hear your voice clearly. Please speak closer to the microphone and record again.";            _isQuietWarning = false;          });        }        return;      }      if (signal.isClipped) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = "Your recording sounds distorted or too loud. Please move slightly further from the microphone and record again.";            _isQuietWarning = false;          });        }        return;      }      if (signal.isExcessivePause) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = "Long pause detected. Try pronouncing the complete phrase smoothly without stopping.";            _isQuietWarning = false;          });        }        return;      }      if (signal.isHighNoise) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = "High background noise detected. Please move to a quieter location for better accuracy.";            _isQuietWarning = false;          });        }        return;      }      _recordedDurationSeconds = learnerWavResult.durationSeconds;      _userVisualWaveform = WavDecoder.extractVisualWaveform(learnerPcm, noOfSamples: 128);      try {        final preprocessedPcm = WavDecoder.prepareLearnerPcm(learnerPcm);        _preprocessedWavBytes = WavDecoder.encodePcmToWavBytes(preprocessedPcm, sampleRate: 16000);      } catch (e) {        debugPrint('Failed to pre-encode preprocessed preview: $e');        _preprocessedWavBytes = null;      }      if (mounted) {        setState(() {          _recordedFilePath = targetPath;          _state = AudioComparisonState.recorded;          _errorMessage = null;          _isQuietWarning = signal.isQuiet;        });        if (isAutoStop) {          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(              content: Text('Maximum recording time reached (15s). You can listen to your recording or try again.'),              backgroundColor: AppColors.gold500,              duration: Duration(seconds: 4),            ),          );        }      }    } catch (e) {      debugPrint('Error finalizing recording: $e');      if (mounted) {        setState(() {          _state = AudioComparisonState.error;          _errorMessage = 'Error parsing recorded audio: ${e.toString().split(':').last.trim()}';          _isQuietWarning = false;        });      }    } finally {      _isStoppingRecording = false;    }  }  Future<void> _recordAgain() async {    await _userPlayer.stop();    setState(() {      _state = AudioComparisonState.idle;      _userVisualWaveform = [];      _scorePercentage = 0.0;      _isMismatchResult = false;      _resultFeedback = "";      _errorMessage = null;      _isQuietWarning = false;      _isStoppingRecording = false;      _preprocessedWavBytes = null;    });    await _startRecording();  }  Future<void> _submitForComparison() async {    if (_items.isEmpty || _recordedFilePath == null || _recordedFilePath!.isEmpty) return;    if (_state != AudioComparisonState.recorded && _state != AudioComparisonState.playing) return;    final currentItem = _items[_currentIndex];    if (!currentItem.isAvailable || !currentItem.isCompatible) {      if (mounted) {        setState(() {          _state = AudioComparisonState.error;          _errorMessage = 'Selected reference run is unverified or incompatible. Please select a verified compatible run.';        });      }      return;    }    HapticService.selection();    await _userPlayer.stop();    await _nativePlayer.stop();    setState(() {      _state = AudioComparisonState.comparing;      _errorMessage = null;    });    try {      // 1. Decode learner audio bytes      Uint8List learnerBytes;      File? learnerFile;      if (kIsWeb) {        final response = await http.get(Uri.parse(_recordedFilePath!));        if (response.statusCode != 200 || response.bodyBytes.isEmpty) {          throw Exception('Failed to load recorded audio in browser.');        }        learnerBytes = response.bodyBytes;      } else {        learnerFile = File(_recordedFilePath!);        if (!await learnerFile.exists()) {          throw Exception('Learner audio recording file not found.');        }        learnerBytes = await learnerFile.readAsBytes();      }      final learnerWavResult = await decodeAudioBytes(learnerBytes);      final learnerPcm = learnerWavResult.pcmSamples;      if (learnerPcm.length < WavDecoder.minimumComparisonSamples) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = 'Recording is too short to compare reliably (minimum 0.35 seconds). Please say the full word or phrase and record again.';          });        }        return;      }      final signal = WavDecoder.analyzeSignal(learnerPcm);      if (signal.isEmptyOrInvalid || signal.isSilent || signal.isQuiet || signal.hasNoSpeech) {        if (mounted) {          setState(() {            _state = AudioComparisonState.error;            _errorMessage = signal.hasNoSpeech                ? "No speech detected. Please speak the phrase clearly into the microphone and record again."                : "We couldn't hear your voice clearly. Please speak closer to the microphone and record again.";            _isQuietWarning = false;          });        }        return;      }      if (signal.isClipped || signal.isExcessivePause || signal.isHighNoise) {        if (mounted) {          final reason = signal.isClipped              ? 'Recording is distorted or too loud. Move farther from the microphone and record again.'              : signal.isExcessivePause                  ? 'A long pause was detected. Say the complete phrase smoothly and record again.'                  : 'High background noise was detected. Move somewhere quieter and record again.';          setState(() {            _state = AudioComparisonState.error;            _errorMessage = reason;            _isQuietWarning = false;          });        }        return;      }      // 2. Load and compare against every verified take of this phrase      final referencePcms = <List<double>>[];      List<double>? primaryReferencePcm;      for (final take in _collectReferenceTakes(currentItem)) {        try {          final pcm = await _fetchAndDecodeNativePcm(currentItem, take);          if (pcm.length < WavDecoder.minimumComparisonSamples) continue;          referencePcms.add(pcm);          primaryReferencePcm ??= pcm;        } catch (e) {          debugPrint('Skipping undecodable reference take ${take.audioPath}: $e');        }      }      if (referencePcms.isEmpty) {        throw Exception('No reference audio could be decoded for this phrase.');      }      _nativeVisualWaveform = WavDecoder.extractVisualWaveform(primaryReferencePcm!, noOfSamples: 128);      // Distances are aggregated in distance space inside the service, then      // mapped once; averaging percentages from a non-linear map double-penalised      // learners who matched one take well.      final referenceSet = PronunciationService.buildReferenceSet(referencePcms);      final score = PronunciationService.compareAgainstReferenceSet(        referenceSet,        learnerPcm,        strictness: PronunciationStrictness.normal,        algorithm: _configuredAlgorithm(),      );      final finalScore = score.overallScore;      if (mounted) {        final isDark = Theme.of(context).brightness == Brightness.dark;        final l10n = ref.read(localizationProvider);        setState(() {          _scorePercentage = finalScore;          _isMismatchResult = score.isMismatch;          _resultFeedback = score.feedback;          _state = AudioComparisonState.result;        });        _showResultPopupModal(context, isDark, l10n);        if (score.isMismatch) {          HapticService.selection();          try {            await _nativePlayer.play(ap.AssetSource('audio/error.MP3'));          } catch (_) {}        } else if (_scorePercentage >= 60.0) {          HapticService.success();          try {            ref.read(studentProvider.notifier).addXp(15);            ref.read(questActionProvider.notifier).updateProgress(QuestType.pronunciation, 1);          } catch (e) {            debugPrint('Error awarding pronunciation XP: $e');          }          try {            await _nativePlayer.play(ap.AssetSource('audio/success.MP3'));          } catch (_) {}        } else {          HapticService.selection();          try {            await _nativePlayer.play(ap.AssetSource('audio/error.MP3'));          } catch (_) {}        }      }    } catch (e) {      debugPrint('Pronunciation evaluation error: $e');      if (mounted) {        setState(() {          _state = AudioComparisonState.error;          _errorMessage = 'Audio comparison failed: ${e.toString().split(':').last.trim()}';        });      }    }  }  @override  Widget build(BuildContext context) {    final isDark = Theme.of(context).brightness == Brightness.dark;    final l10n = ref.watch(localizationProvider);    final datasetAsync = ref.watch(supabaseDatasetEntriesProvider);    return Scaffold(      extendBodyBehindAppBar: true,      appBar: AppBar(        backgroundColor: Colors.transparent,        elevation: 0,        leading: IconButton(          icon: Icon(Icons.arrow_back_rounded, color: isDark ? Colors.white : AppColors.forest900),          onPressed: () => Navigator.pop(context),        ),        title: Text(          l10n.translate('audio_comparison'),          style: AppTypography.label.copyWith(            color: AppColors.gold500,            letterSpacing: 2,            fontWeight: FontWeight.w900,          ),        ),        actions: [          IconButton(            icon: Icon(              Icons.shuffle_rounded,              color: _isShuffled ? AppColors.gold500 : (isDark ? Colors.white70 : AppColors.creamText2),            ),            onPressed: _toggleShuffle,            tooltip: l10n.translate('shuffle_content'),          ),        ],      ),      body: BrandBackground(        child: datasetAsync.when(          data: (entries) {            final isDark = Theme.of(context).brightness == Brightness.dark;            if (_comparisonEntries.isEmpty && entries.isNotEmpty) {              _comparisonEntries = List.from(entries);              final baseEntries = entries                  .where((e) => !e.isSupplementaryReference && e.isCompatible && e.isAvailable)                  .toList();              final primaryEntries = baseEntries.isNotEmpty                  ? baseEntries                  : entries.where((e) => !e.isSupplementaryReference).toList();              const first10Names = ['ama', 'antik', 'bapa', 'dagom', 'gauma', 'isa', 'isu', 'lima', 'makagwas', 'mangud'];                            final first10 = <SupabaseDatasetEntry>[];              final remaining = <SupabaseDatasetEntry>[];              for (final name in first10Names) {                final match = primaryEntries.firstWhere(                  (e) {                    final f = e.folderName.toLowerCase();                    final b = f.split('__').first.split('_').first;                    return f == name || b == name || f.startsWith('${name}__') || f.startsWith('${name}_');                  },                  orElse: () => SupabaseDatasetEntry(folderName: '', title: '', runId: '', isCompatible: false, takes: []),                );                if (match.folderName.isNotEmpty && !first10.contains(match)) {                  first10.add(match);                }              }              for (final entry in primaryEntries) {                if (!first10.contains(entry)) {                  remaining.add(entry);                }              }              while (first10.length < 10 && remaining.isNotEmpty) {                first10.add(remaining.removeAt(0));              }              remaining.sort((a, b) {                int lenCmp = a.folderName.length.compareTo(b.folderName.length);                if (lenCmp != 0) return lenCmp;                return a.folderName.compareTo(b.folderName);              });              final orderedEntries = [...first10, ...remaining];              final studentState = ref.watch(studentProvider);              final xp = studentState.xp;              final unlockedTiers = xp ~/ 2000;              final totalPrimaryCount = orderedEntries.length;              final unlockedCount = (10 + (unlockedTiers * 10)).clamp(10, totalPrimaryCount);              _items = orderedEntries.take(unlockedCount).toList();              if (_isShuffled) _items.shuffle();            }            if (_items.isEmpty) {              return Center(                child: Padding(                  padding: const EdgeInsets.all(24.0),                  child: Column(                    mainAxisAlignment: MainAxisAlignment.center,                    children: [                      Icon(Icons.folder_off_rounded, size: 64, color: isDark ? Colors.white38 : AppColors.creamText3),                      const SizedBox(height: 16),                      Text(                        _comparisonEntries.any((e) => e.isSupplementaryReference)                            ? 'No primary Mansaka dataset references found. dataset_2 takes are available only for additional comparison accuracy.'                            : 'No preprocessed Mansaka dataset entries found in Supabase Storage.',                        textAlign: TextAlign.center,                        style: TextStyle(color: isDark ? Colors.white60 : AppColors.creamText3),                      ),                    ],                  ),                ),              );            }            if (_currentIndex >= _items.length) _currentIndex = 0;            final currentItem = _items[_currentIndex];            return Center(              child: Padding(                padding: const EdgeInsets.all(24.0),                child: Column(                  mainAxisAlignment: MainAxisAlignment.center,                  children: [                    _buildUnlockStatusBanner(isDark, ref.watch(studentProvider).xp, _items.length, _comparisonEntries.where((e) => !e.isSupplementaryReference).length),                    _buildNativeSpeakerCard(isDark, currentItem, l10n),                    const SizedBox(height: 20),                    _buildUserRecordingCard(isDark, l10n),                    const SizedBox(height: 20),                    if (_state == AudioComparisonState.result)                      _buildResultCard(isDark, l10n).animate().scale().fadeIn(),                  ],                ),              ),            );          },          loading: () => const Center(child: CircularProgressIndicator(color: AppColors.gold500)),          error: (e, _) => Center(            child: Padding(              padding: const EdgeInsets.all(24.0),              child: Column(                mainAxisAlignment: MainAxisAlignment.center,                children: [                  const Icon(                    Icons.wifi_off_rounded,                    size: 64,                    color: AppColors.gold500,                  ),                  const SizedBox(height: 16),                  Text(                    'Unable to Connect to Reference Storage',                    textAlign: TextAlign.center,                    style: AppTypography.h3.copyWith(color: isDark ? Colors.white : AppColors.creamText),                  ),                  const SizedBox(height: 8),                  Text(                    'Could not reach Supabase dataset storage. Please check your internet connection and try again.',                    textAlign: TextAlign.center,                    style: AppTypography.body.copyWith(                      color: isDark ? Colors.white60 : AppColors.creamText3,                      fontSize: 13,                    ),                  ),                  const SizedBox(height: 24),                  BrandButton(                    text: 'RETRY CONNECTION',                    onTap: () {                      HapticService.light();                      setState(() {                        _items = [];                        _comparisonEntries = [];                        _currentIndex = 0;                      });                      ref.invalidate(supabaseDatasetEntriesProvider);                    },                    type: BrandButtonType.primary,                    icon: Icons.refresh_rounded,                  ),                ],              ),            ),          ),        ),      ),    );  }  Widget _buildNativeSpeakerCard(bool isDark, SupabaseDatasetEntry item, AppLocalization l10n) {    return Column(      children: [        BrandCard(          padding: const EdgeInsets.all(20),          child: Column(            children: [              Row(                children: [                  const CircleAvatar(                    backgroundColor: AppColors.gold500,                    child: Icon(Icons.record_voice_over_rounded, color: Colors.black),                  ),                  const SizedBox(width: 16),                  Expanded(                    child: Column(                      crossAxisAlignment: CrossAxisAlignment.start,                      children: [                        Text(                          l10n.translate('native_speaker', params: {'lang': 'Mansaka'}),                          style: AppTypography.label.copyWith(color: AppColors.gold500),                        ),                        Text(                          item.title,                          style: AppTypography.h3.copyWith(color: isDark ? Colors.white : AppColors.creamText),                        ),                        Text(                          item.subtitle,                          maxLines: 2,                          overflow: TextOverflow.ellipsis,                          style: AppTypography.body.copyWith(color: isDark ? Colors.white60 : AppColors.creamText2, fontSize: 12),                        ),                      ],                    ),                  ),                  _isLoadingNativeAudio                      ? const SizedBox(width: 40, height: 40, child: CircularProgressIndicator(strokeWidth: 2, color: AppColors.gold500))                      : IconButton(                          onPressed: () => _playNativeAudio(item),                          icon: const Icon(Icons.play_circle_fill_rounded, color: AppColors.gold500, size: 40),                        ),                ],              ),              if (_nativeVisualWaveform.isNotEmpty) ...[                const SizedBox(height: 12),                _buildSimpleWaveformCanvas(_nativeVisualWaveform, AppColors.gold500),              ],            ],          ),        ),        const SizedBox(height: 8),        Row(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            IconButton(              onPressed: _currentIndex > 0 ? _previousItem : null,              icon: Icon(                Icons.arrow_back_ios_new_rounded,                color: _currentIndex > 0 ? AppColors.gold500 : (isDark ? Colors.white10 : Colors.black12),              ),            ),            Text(              l10n.translate('item_progress', params: {                'current': '${_currentIndex + 1}',                'total': '${_items.length}',              }),              style: AppTypography.mono.copyWith(color: isDark ? Colors.white24 : AppColors.creamText3, fontSize: 10),            ),            IconButton(              onPressed: _currentIndex < _items.length - 1 ? _nextItem : null,              icon: Icon(                Icons.arrow_forward_ios_rounded,                color: _currentIndex < _items.length - 1 ? AppColors.gold500 : (isDark ? Colors.white10 : Colors.black12),              ),            ),          ],        ),      ],    );  }  Widget _buildRecordingTipBanner(bool isDark) {    return Container(      margin: const EdgeInsets.only(bottom: 14),      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),      decoration: BoxDecoration(        color: AppColors.gold500.withValues(alpha: 0.12),        borderRadius: BorderRadius.circular(12),        border: Border.all(color: AppColors.gold500.withValues(alpha: 0.35)),      ),      child: Row(        children: [          const Icon(Icons.tips_and_updates_rounded, size: 16, color: AppColors.gold500),          const SizedBox(width: 8),          Expanded(            child: Text(              'For best accuracy: Speak clearly & loudly near the mic, in a quiet space.',              style: AppTypography.caption.copyWith(                color: isDark ? Colors.white70 : AppColors.creamText2,                fontSize: 11,              ),            ),          ),        ],      ),    );  }  Widget _buildUserRecordingCard(bool isDark, AppLocalization l10n) {    return BrandCard(      theme: BrandCardTheme.vibrant,      padding: const EdgeInsets.all(20),      child: Column(        children: [          _buildRecordingTipBanner(isDark),          if (_state == AudioComparisonState.recording) ...[            _buildActiveRecordingIndicator(),          ] else if (_state == AudioComparisonState.comparing) ...[            Column(              children: [                CircularProgressIndicator(color: isDark ? Colors.white : AppColors.forest900),                const SizedBox(height: 16),                Text(l10n.translate('comparing_tones'), style: TextStyle(color: isDark ? Colors.white70 : AppColors.creamText2)),              ],            ),          ] else if (_state == AudioComparisonState.recorded || _state == AudioComparisonState.playing || _state == AudioComparisonState.result) ...[            _buildPlaybackPreviewArea(),          ] else ...[            if (_errorMessage != null) ...[              Text(                _errorMessage!,                textAlign: TextAlign.center,                style: AppTypography.body.copyWith(color: Colors.redAccent, fontSize: 12),              ),              const SizedBox(height: 12),            ] else              Icon(Icons.mic_none_rounded, size: 44, color: isDark ? Colors.white24 : Colors.black26),          ],          const SizedBox(height: 16),          _buildCardActionButtons(l10n),        ],      ),    );  }  Widget _buildActiveRecordingIndicator() {    final min = (_recordingDurationSeconds ~/ 60).toString().padLeft(2, '0');    final sec = (_recordingDurationSeconds % 60).toString().padLeft(2, '0');    return Column(      children: [        Row(          mainAxisAlignment: MainAxisAlignment.center,          children: [            Container(              width: 12,              height: 12,              decoration: const BoxDecoration(                color: Colors.redAccent,                shape: BoxShape.circle,              ),            ).animate(onPlay: (controller) => controller.repeat(reverse: true)).scale(                  begin: const Offset(0.8, 0.8),                  end: const Offset(1.3, 1.3),                  duration: 800.ms,                ),            const SizedBox(width: 8),            Text(              'RECORDING...',              style: AppTypography.label.copyWith(color: Colors.redAccent, fontWeight: FontWeight.w900, letterSpacing: 1.5),            ),            const SizedBox(width: 12),            Text(              '$min:$sec',              style: AppTypography.mono.copyWith(color: AppColors.gold500, fontSize: 16, fontWeight: FontWeight.bold),            ),          ],        ),        const SizedBox(height: 16),        SizedBox(          height: 32,          child: Row(            mainAxisAlignment: MainAxisAlignment.center,            children: List.generate(_liveAmplitudeBars.length, (index) {              final val = _liveAmplitudeBars[index];              return AnimatedContainer(                duration: const Duration(milliseconds: 100),                margin: const EdgeInsets.symmetric(horizontal: 2),                width: 4,                height: (val * 32).clamp(4.0, 32.0),                decoration: BoxDecoration(                  color: AppColors.gold500,                  borderRadius: BorderRadius.circular(2),                ),              );            }),          ),        ),      ],    );  }  Widget _buildPlaybackPreviewArea() {    final isPlaying = _state == AudioComparisonState.playing;    final isDark = Theme.of(context).brightness == Brightness.dark;    return Column(      children: [        Row(          mainAxisAlignment: MainAxisAlignment.spaceBetween,          children: [            Row(              children: [                Icon(                  isPlaying ? Icons.volume_up_rounded : Icons.audiotrack_rounded,                  color: AppColors.gold500,                  size: 18,                ),                const SizedBox(width: 6),                Text(                  'Your Attempt (${_recordedDurationSeconds.toStringAsFixed(1)}s)',                  style: AppTypography.label.copyWith(color: isDark ? Colors.white : AppColors.creamText, fontWeight: FontWeight.bold),                ),              ],            ),            Row(              children: [                IconButton(                  onPressed: isPlaying ? _stopUserAudio : _playUserAudio,                  icon: Icon(                    isPlaying ? Icons.pause_circle_filled_rounded : Icons.play_circle_fill_rounded,                    color: AppColors.gold500,                    size: 32,                  ),                ),              ],            ),          ],        ),        if (_userVisualWaveform.isNotEmpty) ...[          const SizedBox(height: 8),          _buildSimpleWaveformCanvas(_userVisualWaveform, isDark ? Colors.white : AppColors.forest900),        ],        if (_isQuietWarning) ...[          const SizedBox(height: 10),          Container(            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),            decoration: BoxDecoration(              color: AppColors.semanticWarning.withValues(alpha: 0.15),              borderRadius: BorderRadius.circular(10),              border: Border.all(color: AppColors.semanticWarning.withValues(alpha: 0.4)),            ),            child: Row(              children: [                const Icon(Icons.volume_down_rounded, size: 16, color: AppColors.semanticWarning),                const SizedBox(width: 8),                Expanded(                  child: Text(                    'Quiet recording detected. Speak closer to the microphone for best accuracy.',                    style: AppTypography.caption.copyWith(color: isDark ? Colors.white70 : AppColors.creamText2, fontSize: 11),                  ),                ),              ],            ),          ),        ],      ],    );  }  Widget _buildCardActionButtons(AppLocalization l10n) {    if (_state == AudioComparisonState.recording) {      return BrandButton(        text: 'STOP RECORDING',        onTap: _stopRecording,        type: BrandButtonType.primary,        icon: Icons.stop_rounded,      );    }    if (_state == AudioComparisonState.recorded || _state == AudioComparisonState.playing || _state == AudioComparisonState.result) {      return Column(        children: [          BrandButton(            text: 'COMPARE PRONUNCIATION',            onTap: _state == AudioComparisonState.comparing ? null : _submitForComparison,            type: BrandButtonType.primary,            icon: Icons.analytics_rounded,          ),          const SizedBox(height: 8),          BrandButton(            text: 'RECORD AGAIN',            onTap: _recordAgain,            type: BrandButtonType.secondary,            icon: Icons.refresh_rounded,          ),        ],      );    }    if (_state == AudioComparisonState.error) {      return BrandButton(        text: 'RECORD AGAIN',        onTap: _recordAgain,        type: BrandButtonType.primary,        icon: Icons.refresh_rounded,      );    }    return BrandButton(      text: l10n.translate('start_recording'),      onTap: _startRecording,      type: BrandButtonType.secondary,      icon: Icons.mic_rounded,    );  }  Widget _buildSimpleWaveformCanvas(List<double> waveform, Color color) {    return SizedBox(      height: 36,      width: double.infinity,      child: CustomPaint(        painter: WaveformPainter(waveform: waveform, color: color),      ),    );  }  Widget _buildResultCard(bool isDark, AppLocalization l10n) {    final percentage = _scorePercentage.toInt();    // High contrast dark font colors for excellent legibility over gold card background    Color scoreColor = const Color(0xFF4E342E);    String feedback = l10n.translate('feedback_good_effort');    String title = l10n.translate('acoustic_match');    if (_isMismatchResult) {      scoreColor = const Color(0xFFBF360C);      title = 'NOT THE TARGET PHRASE';      feedback = _resultFeedback.isNotEmpty          ? _resultFeedback          : "That doesn't sound like the target phrase. Please listen and record the phrase shown.";    } else if (_scorePercentage >= 80.0) {      scoreColor = const Color(0xFF1B5E20);      feedback = _resultFeedback.isNotEmpty ? _resultFeedback : l10n.translate('feedback_excellent');    } else if (_scorePercentage < 60.0) {      scoreColor = const Color(0xFFBF360C);      feedback = _resultFeedback.isNotEmpty ? _resultFeedback : l10n.translate('feedback_needs_work');    } else if (_resultFeedback.isNotEmpty) {      feedback = _resultFeedback;    }    return BrandCard(      theme: BrandCardTheme.gold,      padding: const EdgeInsets.all(20),      child: Column(        children: [          Text(            title,            style: AppTypography.label.copyWith(              color: Colors.black87,              fontWeight: FontWeight.w900,              letterSpacing: 1.5,            ),          ),          const SizedBox(height: 8),          Text(            '$percentage%',            style: AppTypography.displayBold.copyWith(              color: scoreColor,              fontSize: 52,              fontWeight: FontWeight.w900,            ),          ),          const SizedBox(height: 8),          Text(            feedback,            textAlign: TextAlign.center,            style: AppTypography.body.copyWith(              color: Colors.black87,              fontWeight: FontWeight.bold,              fontSize: 14,            ),          ),          if (!_isMismatchResult && _scorePercentage >= 60.0) ...[            const SizedBox(height: 16),            Container(              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),              decoration: BoxDecoration(                color: const Color(0xFF1B5E20).withValues(alpha: 0.12),                borderRadius: BorderRadius.circular(16),                border: Border.all(color: const Color(0xFF1B5E20).withValues(alpha: 0.3)),              ),              child: Row(                mainAxisSize: MainAxisSize.min,                children: [                  const Icon(Icons.auto_awesome_rounded, size: 16, color: Color(0xFF1B5E20)),                  const SizedBox(width: 8),                  Text(                    '+15 XP Awarded!',                    style: AppTypography.label.copyWith(                      color: const Color(0xFF1B5E20),                      fontSize: 12,                      fontWeight: FontWeight.w900,                    ),                  ),                ],              ),            ),          ],        ],      ),    );  }  void _showResultPopupModal(BuildContext context, bool isDark, AppLocalization l10n) {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: Colors.transparent,      builder: (modalContext) {        return Container(          padding: const EdgeInsets.all(24),          decoration: BoxDecoration(            color: isDark ? AppColors.forest800 : AppColors.creamBg,            borderRadius: const BorderRadius.vertical(top: Radius.circular(32)),            border: Border.all(              color: AppColors.gold500.withValues(alpha: 0.3),            ),          ),          child: Column(            mainAxisSize: MainAxisSize.min,            children: [              Row(                mainAxisAlignment: MainAxisAlignment.spaceBetween,                children: [                  Text(                    'Pronunciation Assessment',                    style: AppTypography.h3.copyWith(                      color: isDark ? Colors.white : AppColors.forest900,                      fontSize: 18,                    ),                  ),                  IconButton(                    icon: Icon(Icons.close_rounded, color: isDark ? Colors.white70 : Colors.black54),                    onPressed: () => Navigator.of(modalContext).pop(),                  ),                ],              ),              const SizedBox(height: 16),              _buildResultCard(isDark, l10n),              const SizedBox(height: 24),              Row(                children: [                  Expanded(                    child: BrandButton(                      text: 'RECORD AGAIN',                      onTap: () {                        Navigator.of(modalContext).pop();                        _recordAgain();                      },                      type: BrandButtonType.secondary,                      icon: Icons.refresh_rounded,                    ),                  ),                  const SizedBox(width: 12),                  Expanded(                    child: BrandButton(                      text: 'DONE',                      onTap: () {                        Navigator.of(modalContext).pop();                      },                      type: BrandButtonType.primary,                      icon: Icons.check_circle_rounded,                    ),                  ),                ],              ),            ],          ),        );      },    );  }}class WaveformPainter extends CustomPainter {  final List<double> waveform;  final Color color;  WaveformPainter({required this.waveform, required this.color});  @override  void paint(Canvas canvas, Size size) {    if (waveform.isEmpty) return;    final paint = Paint()      ..color = color      ..strokeWidth = 2.0      ..strokeCap = StrokeCap.round;    final barWidth = size.width / waveform.length;    final centerY = size.height / 2;    for (int i = 0; i < waveform.length; i++) {      final x = i * barWidth;      final h = (waveform[i] * size.height).clamp(2.0, size.height);      canvas.drawLine(        Offset(x, centerY - h / 2),        Offset(x, centerY + h / 2),        paint,      );    }  }  @override  bool shouldRepaint(covariant WaveformPainter oldDelegate) {    return oldDelegate.waveform != waveform || oldDelegate.color != color;  }}